-- beckon: Claude Code driven from Slack, on your own machine and subscription (OpenYard team project).
-- It has no site of its own; `url` is the repository.
INSERT INTO projects (slug, name, type, kinds, status, tagline, description, url, repo, license, logo, logo_style, image, og, color, maintainers, tags, team, featured, swarm, added, created_at, updated_at, install) VALUES
('beckon', 'beckon', 'open-source', '["dev"]', 'beta',
 '{"en":"Run Claude Code from Slack, on your own machine and subscription","vi":"Điều khiển Claude Code từ Slack, chạy trên máy và gói Claude của chính bạn"}',
 '{"en":"Mention @beckon with a task and it runs the official claude CLI on your machine, in a fresh git worktree of the repository linked to the channel. Each Slack thread is one Claude session: the steps show live in a single message, and the answer opens with a one-line summary. Deploys, pushes to main, merges, migrations, app releases and publishing always wait for an Allow button in Slack, and the hook fails closed. It connects with Socket Mode, so it needs no public URL, and runs as a launchd or systemd service. Made for one person''s own work on their own Claude plan.","vi":"Gọi @beckon kèm một việc, nó chạy claude CLI chính chủ trên máy bạn, trong một git worktree mới của repo gắn với kênh. Mỗi thread Slack là một phiên Claude: các bước hiện trực tiếp trong một tin nhắn, câu trả lời mở đầu bằng một câu tóm tắt. Deploy, push lên main, merge, migration, phát hành app và publish luôn chờ bạn bấm Allow trong Slack, và khi không hỏi được thì mặc định từ chối. Kết nối bằng Socket Mode nên không cần URL công khai, chạy nền bằng launchd hoặc systemd. Dành cho việc của chính bạn, trên gói Claude của chính bạn."}',
 'https://github.com/openyard-cloud/beckon', 'https://github.com/openyard-cloud/beckon', 'MIT',
 '/logos/beckon.svg', 'tile', '/images/beckon.webp', NULL, '#f0a530',
 '["thihodev"]', '["claude-code","slack","developer-tools"]', 1, 1, NULL,
 '2026-11-21', 1795235650186, 1795235650186,
 '[{"label":{"en":"macOS or Linux","vi":"macOS hoặc Linux"},"cmd":"npm install -g github:openyard-cloud/beckon && beckon init","note":{"en":"Then create the Slack app from beckon manifest, put both tokens in ~/.beckon/env, run beckon doctor and beckon service install. Needs Node 22 and Claude Code logged in.","vi":"Sau đó tạo Slack app từ beckon manifest, điền hai token vào ~/.beckon/env, chạy beckon doctor và beckon service install. Cần Node 22 và Claude Code đã đăng nhập."}}]');
